"""App wiring. Area builders use setup hooks and do not edit this file."""

import asyncio
import importlib
import ipaddress
import logging
import secrets
from contextlib import asynccontextmanager
from dataclasses import dataclass, field
from typing import Any

from fastapi import FastAPI, HTTPException, Request
from fastapi.responses import JSONResponse
from psycopg_pool import AsyncConnectionPool

from illo.brain.client import BrainClient
from illo.brain.server import endpoint
from illo.config import Config
from illo.db import create_pool, migrate, one
from illo.gateway import Gateway
from illo.routines.scheduler import Scheduler
from illo.slackapi import ActionRouter
from illo.tools.registry import Registry
from illo.workspace import Workspace, fingerprint, load_workspace

log = logging.getLogger(__name__)
SETUP_MODULES = (
    "illo.channels.slack",
    "illo.channels.email",
    "illo.channels.mcp",
    "illo.channels.signals",
    "illo.sources.search",
    "illo.sources.github",
    "illo.sources.slack_index",
    "illo.sources.drive",
    "illo.sources.archive",
    "illo.connectors.mcp_client",
    "illo.connectors.google",
    "illo.connectors.oauth",
    "illo.connectors.chat",
    "illo.tasks.list_page",
    "illo.connectors.chatgpt_oauth",
    "illo.routines.scheduler",
    "illo.routines.digest",
    "illo.routines.reminders",
    "illo.routines.stale",
    "illo.routines.heartbeat",
    "illo.asks",
    "illo.notes",
    "illo.memory",
    "collectors",
    "collectors.t3",
    "collectors.hooks",
)


@dataclass
class AppContext:
    config: Config
    pool: AsyncConnectionPool
    workspace: Workspace
    registry: Registry
    brain_client: Any
    app: FastAPI
    slack_client: Any = None
    github_client: Any = None
    # Card buttons: an area registers a handler for its action_id prefix.
    slack_actions: ActionRouter = field(default_factory=ActionRouter)
    # Approved drafts: an area registers `async fn(ctx, draft_row)` for its draft kind.
    draft_performers: dict[str, Any] = field(default_factory=dict)
    gateway: Gateway = field(init=False)
    scheduler: Scheduler = field(init=False)
    reload_lock: asyncio.Lock = field(default_factory=asyncio.Lock)

    def __post_init__(self):
        self.scheduler = Scheduler(self)
        self.gateway = Gateway(self)

    def every(self, seconds: float, fn):
        """Register a repeated job from a module setup hook."""
        return self.scheduler.every(seconds, fn)

    def cron(self, expr: str, fn):
        """Register a cron job from a module setup hook."""
        return self.scheduler.cron(expr, fn)

    async def reload(self) -> None:
        """Validate first. Keep the old workspace if validation or sync fails."""
        async with self.reload_lock:
            workspace = load_workspace(self.config.workspace_dir)
            workspace.config.brain.check_runtime(self.config.brain_runtime)
            async with self.pool.connection() as conn:
                await workspace.sync_people(conn)
            self.workspace = workspace


def create_app(config: Config | None = None, *, brain_client=None, pool=None) -> FastAPI:
    """No channel token is required. Tests can inject the pool and fake brain."""
    config = config or Config.from_env()

    @asynccontextmanager
    async def lifespan(app):
        owned_pool = pool is None
        db_pool = pool or create_pool(
            config.database_url, min_size=config.pool_min_size, max_size=config.pool_max_size
        )
        if owned_pool:
            await db_pool.open(wait=True)
        ctx = None
        try:
            async with db_pool.connection() as conn:
                if config.migrate_on_start:
                    await migrate(conn)
                workspace = load_workspace(config.workspace_dir)
                workspace.config.brain.check_runtime(config.brain_runtime)
                await workspace.sync_people(conn)
            registry = Registry()
            registry.discover()
            ctx = AppContext(
                config,
                db_pool,
                workspace,
                registry,
                brain_client or BrainClient(config.brain_url),
                app,
            )
            app.state.ctx = ctx
            for name in SETUP_MODULES:
                await importlib.import_module(name).setup(ctx)

            async def check_workspace():
                if fingerprint(config.workspace_dir) != ctx.workspace.fingerprint:
                    await ctx.reload()

            ctx.every(config.workspace_check_seconds, check_workspace)
            yield
        finally:
            if ctx:
                await ctx.scheduler.close()
            if owned_pool:
                await db_pool.close()

    app = FastAPI(title="Illo", lifespan=lifespan)
    app.add_api_route("/brain/mcp", endpoint, methods=["POST"])

    @app.get("/healthz")
    async def healthz(request: Request):
        try:
            async with request.app.state.ctx.pool.connection(timeout=3) as conn:
                await one(conn, "SELECT 1")
            return {"status": "ok", "database": "ok", "revision": config.revision}
        except Exception:
            return JSONResponse(
                {"status": "error", "database": "unavailable", "revision": config.revision},
                status_code=503,
            )

    @app.post("/admin/reload")
    async def reload(request: Request):
        host = request.client.host if request.client else ""
        try:
            loopback = ipaddress.ip_address(host).is_loopback
        except ValueError:
            loopback = False
        expected = config.reload_token.get_secret_value() if config.reload_token else ""
        if (
            not loopback
            or not expected
            or not secrets.compare_digest(
                request.headers.get("authorization", ""), f"Bearer {expected}"
            )
        ):
            raise HTTPException(403, "Workspace reload is not allowed")
        try:
            await request.app.state.ctx.reload()
        except ValueError as exc:
            raise HTTPException(400, str(exc)) from None
        return {"status": "reloaded"}

    return app
